import os, subprocess, time
import numpy as np
from PIL import Image
from scipy.ndimage import binary_erosion, distance_transform_edt
ROOT='/app/output'; T=np.asarray(Image.open('/app/target.png').convert('RGB')).mean(2)<100
TB=T & ~binary_erosion(T); DT=distance_transform_edt(~TB)

def measure():
 C=np.load(ROOT+'/current_ink.npy')>=.5; CB=C & ~binary_erosion(C); DC=distance_transform_edt(~CB); best=None
 for dy in range(-3,4):
  for dx in range(-3,4):
   y0,y1=max(0,dy),min(1024,1024+dy); x0,x1=max(0,dx),min(1024,1024+dx)
   cy0,cy1=max(0,-dy),min(1024,1024-dy); cx0,cx1=max(0,-dx),min(1024,1024-dx)
   tt=T[y0:y1,x0:x1]; cc=C[cy0:cy1,cx0:cx1]
   iou=np.count_nonzero(tt&cc)/max(1,np.count_nonzero(tt|cc))
   bt=TB[y0:y1,x0:x1]; bc=CB[cy0:cy1,cx0:cx1]
   p=np.mean(DC[cy0:cy1,cx0:cx1][bt]<=4.51); r=np.mean(DT[y0:y1,x0:x1][bc]<=4.51)
   bf=2*p*r/max(1e-9,p+r); obj=.55*iou+.45*bf
   if best is None or obj>best[0]:best=(obj,iou,bf,dx,dy)
 return best

pm={i:1.0 for i in range(1,7)}
def run():
 e=os.environ.copy();e['NO_SCORE']='1'
 for i,v in pm.items(): e[f'S{i}_PM']=str(v)
 p=subprocess.run(['python','/app/output/gen.py'],env=e,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,text=True)
 if p.returncode: raise RuntimeError(p.stderr[-2000:])
 return measure()
start=time.time(); cur=run();print('BASE',cur,flush=True)
for i in range(1,7):
